body.script:
let ordersData = [];
const csrfToken = '';
const statusRank = { awaiting_confirmation: 1, waiting: 2, preparing: 3, ready: 4, delivered: 5, completed: 6 };
const activeStatuses = ['awaiting_confirmation', 'waiting', 'preparing', 'ready'];
let activeFilter = 'active';
let isActionInProgress = false;
let lastErrorMessage = '';
let monitorActive = true;
let pollingTimer = null;
let activeFetchController = null;

function byId(id) {
    return document.getElementById(id);
}

function canRenderMonitor() {
    return monitorActive && document.querySelector('.rs-kds') && byId('orders-grid') && byId('current-order-pane');
}

function stopMonitor() {
    monitorActive = false;
    if (pollingTimer) {
        clearInterval(pollingTimer);
        pollingTimer = null;
    }
    if (activeFetchController) {
        activeFetchController.abort();
        activeFetchController = null;
    }
}

window.addEventListener('pagehide', stopMonitor);
window.addEventListener('beforeunload', stopMonitor);

function processRawOrders(rawOrders) {
    return (rawOrders || []).map(order => {
        const lines = order.lines || [];
        const dateValue = order.date_str ? new Date(order.date_str.replace(' ', 'T')) : null;
        const waitMinutes = Number.isFinite(order.wait_minutes)
            ? order.wait_minutes
            : (dateValue ? Math.max(0, Math.floor((Date.now() - dateValue.getTime()) / 60000)) : 0);
        const statusGroup = order.status_group || (
            order.state === 'draft' ? 'awaiting_confirmation' :
            ['confirmed', 'sent_pos', 'pos_failed'].includes(order.state) ? 'waiting' :
            order.state === 'kitchen_preparing' ? 'preparing' :
            order.state === 'kitchen_ready' ? 'ready' :
            order.state === 'delivered' ? 'delivered' : 'completed'
        );
        return {
            ...order,
            name: order.name || order.number || '',
            guest: order.guest || '',
            guest_phone: order.guest_phone || '',
            lines: lines,
            status_group: statusGroup,
            wait_minutes: waitMinutes,
            time_str: order.time_str || (dateValue ? dateValue.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''),
            total_items: Number.isFinite(order.total_items) ? order.total_items : lines.reduce((sum, line) => sum + Number(line.qty || 0), 0),
        };
    });
}

function renderSummary() {
    if (!canRenderMonitor()) {
        return;
    }
    const summary = ordersData.reduce((acc, order) => {
        if (order.status_group === 'awaiting_confirmation') {
            acc.awaiting_confirmation += 1;
        } else if (order.status_group === 'waiting') {
            acc.waiting += 1;
        } else if (order.status_group === 'preparing') {
            acc.preparing += 1;
        } else if (order.status_group === 'ready') {
            acc.ready += 1;
        } else if (['delivered', 'completed'].includes(order.status_group)) {
            acc.completed += 1;
        }
        return acc;
    }, { awaiting_confirmation: 0, waiting: 0, preparing: 0, ready: 0, completed: 0 });

    const summaryAwaiting = byId('summary-awaiting_confirmation');
    const summaryWaiting = byId('summary-waiting');
    const summaryPreparing = byId('summary-preparing');
    const summaryReady = byId('summary-ready');
    const summaryCompleted = byId('summary-completed');
    if (!summaryAwaiting || !summaryWaiting || !summaryPreparing || !summaryReady || !summaryCompleted) {
        return;
    }
    summaryAwaiting.textContent = summary.awaiting_confirmation;
    summaryWaiting.textContent = summary.waiting;
    summaryPreparing.textContent = summary.preparing;
    summaryReady.textContent = summary.ready;
    summaryCompleted.textContent = summary.completed;
}

function escapeHtml(value) {
    return String(value || '').replace(/[&<>"']/g, function(match) {
        return {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        }[match];
    });
}

function money(value) {
    return '$' + Number(value || 0).toFixed(2);
}

function statusLabel(order) {
    const labels = {
        awaiting_confirmation: 'New Order',
        waiting: 'Sent to POS',
        preparing: 'Cooking',
        ready: 'Ready to Deliver',
        delivered: 'Delivered',
        completed: 'Completed',
    };
    return labels[order.status_group] || order.state_label || order.status_group || '';
}

function waitClass(minutes) {
    if (minutes >= 30) {
        return 'is-hot';
    }
    if (minutes >= 15) {
        return 'is-warm';
    }
    return '';
}

function waitLabel(minutes) {
    if (minutes >= 60) {
        return 'Overdue ' + minutes + ' min';
    }
    if (minutes >= 30) {
        return 'Late ' + minutes + ' min';
    }
    return minutes + ' min';
}

function sortedOrders(source) {
    return [...source].sort((a, b) => {
        const rankDiff = (statusRank[a.status_group] || 9) - (statusRank[b.status_group] || 9);
        if (rankDiff) {
            return rankDiff;
        }
        return (a.id || 0) - (b.id || 0);
    });
}

function filteredOrders() {
    const searchInput = byId('rs-search');
    const query = searchInput ? searchInput.value.trim().toLowerCase() : '';
    return sortedOrders(ordersData).filter(order => {
        const statusMatch =
            activeFilter === 'all' ||
            (activeFilter === 'active' && activeStatuses.includes(order.status_group)) ||
            order.status_group === activeFilter ||
            (activeFilter === 'completed' && order.status_group === 'delivered');
        const queryMatch = !query ||
            String(order.room || '').toLowerCase().includes(query) ||
            String(order.guest || '').toLowerCase().includes(query) ||
            String(order.guest_phone || '').toLowerCase().includes(query) ||
            String(order.number || '').toLowerCase().includes(query) ||
            String(order.name || '').toLowerCase().includes(query);
        return statusMatch && queryMatch;
    });
}

function actionButton(order, action, label, enabled, cssClass) {
    if (!enabled) {
        return '';
    }
    const disabledAttr = (enabled && !isActionInProgress) ? '' : ' disabled="disabled"';
    const opacityStyle = (enabled && !isActionInProgress) ? '' : ' style="opacity: 0.5;"';
    return '<button class="rs-action-btn ' + cssClass + '" type="button"' + disabledAttr + opacityStyle +
        ' data-order-id="' + order.id + '" data-order-action="' + action + '">' + label + '</button>';
}

async function executeOrderAction(orderId, actionName) {
    if (!canRenderMonitor() || isActionInProgress) return;
    isActionInProgress = true;
    lastErrorMessage = '';

    // Disable all buttons immediately
    document.querySelectorAll('.rs-action-btn').forEach(btn => {
        btn.disabled = true;
        btn.style.opacity = '0.5';
    });

    try {
        activeFetchController = new AbortController();
        const response = await fetch('/room-service/order-display/action/json', {
            method: 'POST',
            signal: activeFetchController.signal,
            headers: {
                'Content-Type': 'application/json',
                'X-Csrftoken': csrfToken,
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    order_id: orderId,
                    action_name: actionName
                }
            })
        });
        if (!canRenderMonitor()) {
            return;
        }

        const data = await response.json();
        if (!canRenderMonitor()) {
            return;
        }
        if (data && data.result) {
            if (data.result.success) {
                // Succeeded! Instantly fetch updated orders
                await fetchUpdatedOrders();
            } else {
                lastErrorMessage = data.result.error || 'An unknown error occurred.';
                updateUI();
            }
        } else if (data && data.error) {
            lastErrorMessage = data.error.message || 'Server error occurred.';
            updateUI();
        }
    } catch (e) {
        if (e.name === 'AbortError') {
            return;
        }
        console.error("Action error:", e);
        lastErrorMessage = e.message || 'Network error occurred.';
        updateUI();
    } finally {
        activeFetchController = null;
        isActionInProgress = false;
    }
}

function renderOrder(order) {
    if (!canRenderMonitor()) {
        return;
    }
    const pane = byId('current-order-pane');
    if (!pane) {
        return;
    }
    if (!order) {
        pane.innerHTML = '<div class="rs-panel-empty">' +
            '<div class="rs-panel-empty-icon">--</div>' +
            '<div style="font-size: 22px; font-weight: 900; margin-top: 10px;">No active orders</div>' +
            '<div style="font-size: 15px; margin-top: 6px;">New room service orders will appear here.</div>' +
        '</div>';
        return;
    }

    let linesHtml = order.lines.length ? '' : '<div class="rs-item-row"><div></div><div class="rs-item-name">No items found</div></div>';
    order.lines.forEach(line => {
        const note = line.note ? '<div class="rs-item-note">' + escapeHtml(line.note) + '</div>' : '';
        linesHtml += '<div class="rs-item-row">' +
            '<div class="rs-item-qty">' + escapeHtml(line.qty) + '</div>' +
            '<div>' +
                '<div class="rs-item-name">' + escapeHtml(line.name) + '</div>' +
                note +
            '</div>' +
        '</div>';
    });

    let noteHtml = '';
    if (order.note) {
        noteHtml = '<div class="rs-note-box">' +
            '<strong>Guest Note</strong><br/>' + escapeHtml(order.note) +
        '</div>';
    }

    let errorHtml = '';
    if (lastErrorMessage) {
        errorHtml = '<div class="rs-error-box" style="background: #fdf2f2; border: 1px solid #f8b4b4; color: #9b1c1c; border-left: 5px solid #e02424; border-radius: 8px; margin-top: 14px; padding: 12px; font-size: 14px; font-weight: 600;">' +
            '<strong>Error occurred:</strong><br/>' + escapeHtml(lastErrorMessage) +
        '</div>';
    }

    const waitSeverity = waitClass(order.wait_minutes);
    const acceptEnabled = order.state === 'draft';
    const preparingEnabled = ['sent_pos', 'pos_failed'].includes(order.state);
    const readyEnabled = order.state === 'kitchen_preparing';
    const completeEnabled = order.state === 'kitchen_ready';
    const actionsHtml =
        actionButton(order, 'accept', 'Accept', acceptEnabled, 'rs-action-accept') +
        actionButton(order, 'preparing', 'Start Cooking', preparingEnabled, 'rs-action-preparing') +
        actionButton(order, 'ready', 'Ready to Deliver', readyEnabled, 'rs-action-ready') +
        actionButton(order, 'complete', 'Complete', completeEnabled, 'rs-action-complete');
    const actionBlock = actionsHtml ?
        '<div class="rs-actions">' + actionsHtml + '</div>' :
        '<div class="rs-status-note">' + escapeHtml(statusLabel(order)) + '</div>';
    const contactHtml = '<div class="rs-current-contact">' +
        '<div class="rs-contact-chip"><div class="rs-contact-label">Room</div><div class="rs-contact-value">' + escapeHtml(order.room || '-') + '</div></div>' +
        '<div class="rs-contact-chip"><div class="rs-contact-label">Guest</div><div class="rs-contact-value">' + escapeHtml(order.guest || '-') + '</div></div>' +
        '<div class="rs-contact-chip"><div class="rs-contact-label">Phone</div><div class="rs-contact-value">' + escapeHtml(order.guest_phone || '-') + '</div></div>' +
    '</div>';

    pane.innerHTML = '<div class="rs-current-header">' +
        '<div>' +
            '<div class="rs-current-number">Order ' + escapeHtml(order.number) + '</div>' +
            contactHtml +
        '</div>' +
        '<div style="display: flex; align-items: center; gap: 12px;">' +
            '<button type="button" data-print-order-id="' + order.id + '" class="rs-print-btn" title="Print Receipt">' +
                '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">' +
                    '<path d="M19 8H5c-1.66 0-3 1.34-3 3v6h4v4h12v-4h4v-6c0-1.66-1.34-3-3-3zm-3 11H8v-5h8v5zm3-7c-.55 0-1-.45-1-1s.45-1 1-1 1 .45 1 1-.45 1-1 1zm-1-9H6v4h12V3z"/>' +
                '</svg>' +
            '</button>' +
            '<span class="rs-status-pill status-' + order.status_group + '">' + escapeHtml(statusLabel(order)) + '</span>' +
        '</div>' +
    '</div>' +
    '<div class="rs-current-body">' +
        '<div class="rs-meta-grid">' +
            '<div class="rs-meta-box"><div class="rs-meta-label">Order Date & Time</div><div class="rs-meta-value">' + escapeHtml(order.date_str) + '</div></div>' +
            '<div class="rs-meta-box"><div class="rs-meta-label">Waiting Time</div><div class="rs-meta-value rs-wait ' + waitSeverity + '">' + waitLabel(order.wait_minutes) + '</div></div>' +
            '<div class="rs-meta-box"><div class="rs-meta-label">Total Items</div><div class="rs-meta-value">' + escapeHtml(order.total_items) + '</div></div>' +
            '<div class="rs-meta-box"><div class="rs-meta-label">Total Amount</div><div class="rs-meta-value">' + money(order.total) + '</div></div>' +
        '</div>' +
        '<div class="rs-section-title">Ordered Items</div>' +
        '<div class="rs-items-list">' + linesHtml + '</div>' +
        noteHtml +
        errorHtml +
    '</div>' +
    '<div class="rs-current-footer">' + actionBlock + '</div>';
}

function printOrderReceipt(orderId) {
    window.open('/report/html/hotel_room_service_qr.report_room_service_order_template/' + orderId, '_blank');
}

function renderCards() {
    if (!canRenderMonitor()) {
        return;
    }
    const grid = byId('orders-grid');
    if (!grid) {
        return;
    }
    const orders = filteredOrders();
    const selectedId = sessionStorage.getItem('selected_order_id');
    if (!orders.length) {
        grid.innerHTML = '<div class="rs-empty">No orders match the current search and filter.</div>';
        renderOrder(null);
        return;
    }

    // Save current scroll position of the grid
    const scrollContainer = grid.parentElement;
    const scrollPos = scrollContainer ? scrollContainer.scrollTop : 0;

    grid.innerHTML = orders.map(order => {
        const waitSeverity = waitClass(order.wait_minutes);
        const active = String(order.id) === selectedId ? ' active' : '';
        return '<article class="rs-card status-' + order.status_group + ' ' + waitSeverity + active + '" data-order-id="' + order.id + '" role="button" tabindex="0">' +
            '<div class="rs-card-head">' +
                '<div><div class="rs-card-number">Order ' + escapeHtml(order.number) + '</div><div class="rs-card-room">Room ' + escapeHtml(order.room) + '</div></div>' +
                '<span class="rs-status-pill status-' + order.status_group + '">' + escapeHtml(statusLabel(order)) + '</span>' +
            '</div>' +
            '<div class="rs-card-body">' +
                '<div class="rs-card-metric"><div class="rs-card-metric-label">Items</div><div class="rs-card-metric-value">' + escapeHtml(order.total_items) + ' Items</div></div>' +
                '<div class="rs-card-metric"><div class="rs-card-metric-label">Order Time</div><div class="rs-card-metric-value">' + escapeHtml(order.time_str) + '</div></div>' +
                '<div class="rs-card-metric"><div class="rs-card-metric-label">Waiting</div><div class="rs-card-metric-value rs-wait ' + waitSeverity + '">' + waitLabel(order.wait_minutes) + '</div></div>' +
                '<div class="rs-card-metric"><div class="rs-card-metric-label">Phone</div><div class="rs-card-metric-value">' + escapeHtml(order.guest_phone || '-') + '</div></div>' +
            '</div>' +
        '</article>';
    }).join('');

    // Restore scroll position
    if (scrollContainer) {
        scrollContainer.scrollTop = scrollPos;
    }

    const selected = orders.find(order => String(order.id) === selectedId) || orders[0];
    selectOrder(selected.id, true);
}

function resetBoardScroll() {
    const board = document.querySelector('.rs-board');
    if (board) {
        board.scrollTop = 0;
    }
}

function selectOrder(orderId, skipRenderCards) {
    if (!canRenderMonitor()) {
        return;
    }
    const selectedOrder = ordersData.find(order => order.id === Number(orderId));
    if (!selectedOrder) {
        renderOrder(null);
        return;
    }
    renderOrder(selectedOrder);
    sessionStorage.setItem('selected_order_id', String(orderId));

    document.querySelectorAll('.rs-card').forEach(card => {
        if (card.getAttribute('data-order-id') === String(orderId)) {
            card.classList.add('active');
        } else {
            card.classList.remove('active');
        }
    });
}

const ordersGrid = byId('orders-grid');
if (ordersGrid) {
    ordersGrid.addEventListener('click', event => {
        const card = event.target.closest('.rs-card[data-order-id]');
        if (card) {
            selectOrder(card.dataset.orderId);
        }
    });
    ordersGrid.addEventListener('keydown', event => {
        if (event.key !== 'Enter' && event.key !== ' ') {
            return;
        }
        const card = event.target.closest('.rs-card[data-order-id]');
        if (card) {
            event.preventDefault();
            selectOrder(card.dataset.orderId);
        }
    });
}

const currentOrderPane = byId('current-order-pane');
if (currentOrderPane) {
    currentOrderPane.addEventListener('click', event => {
        const actionButton = event.target.closest('[data-order-action][data-order-id]');
        if (actionButton) {
            executeOrderAction(Number(actionButton.dataset.orderId), actionButton.dataset.orderAction);
            return;
        }
        const printButton = event.target.closest('[data-print-order-id]');
        if (printButton) {
            printOrderReceipt(Number(printButton.dataset.printOrderId));
        }
    });
}

const searchInput = byId('rs-search');
if (searchInput) {
    searchInput.addEventListener('input', renderCards);
}

function applyFilter(status) {
    activeFilter = status;

    // Update active class on toolbar buttons
    document.querySelectorAll('.rs-filter').forEach(filter => {
        if (filter.dataset.status === status) {
            filter.classList.add('active');
        } else {
            filter.classList.remove('active');
        }
    });

    // Update active class on summary cards
    document.querySelectorAll('.rs-summary-card').forEach(card => {
        if (card.dataset.status === status) {
            card.classList.add('active');
        } else {
            card.classList.remove('active');
        }
    });

    if (canRenderMonitor()) {
        renderCards();
        resetBoardScroll();
    }
}

const filters = byId('rs-filters');
if (filters) {
    filters.addEventListener('click', event => {
    const button = event.target.closest('.rs-filter');
    if (!button) {
        return;
    }
    applyFilter(button.dataset.status);
    });
}

const summary = document.querySelector('.rs-summary');
if (summary) {
    summary.addEventListener('click', event => {
        const card = event.target.closest('.rs-summary-card');
        if (!card) {
            return;
        }
        applyFilter(card.dataset.status);
    });
}

function setConnectionStatus(status) {
    const box = byId('rs-conn-status');
    const dot = byId('rs-conn-dot');
    const text = byId('rs-conn-text');
    if (!box || !dot || !text) return;
    if (status === 'live') {
        box.style.background = '#f0fdf4';
        box.style.color = '#166534';
        box.style.border = '1px solid #bbf7d0';
        dot.style.background = '#16a34a';
        text.textContent = 'Live';
    } else if (status === 'disconnected') {
        box.style.background = '#fef2f2';
        box.style.color = '#991b1b';
        box.style.border = '1px solid #fecaca';
        dot.style.background = '#dc2626';
        text.textContent = 'Disconnected';
    } else {
        box.style.background = '#e2e8f0';
        box.style.color = '#475569';
        box.style.border = '1px solid #cbd5e1';
        dot.style.background = '#94a3b8';
        text.textContent = 'Connecting...';
    }
}

function updateSessionWarning(closedSessions) {
    const banner = byId('rs-session-warning-banner');
    const listSpan = byId('rs-closed-sessions-list');
    if (!banner || !listSpan) return;
    if (closedSessions && closedSessions.length) {
        listSpan.textContent = closedSessions.join(', ');
        banner.style.display = 'flex';
    } else {
        banner.style.display = 'none';
    }
}

async function fetchUpdatedOrders() {
    if (!canRenderMonitor()) {
        return;
    }
    try {
        activeFetchController = new AbortController();
        const response = await fetch('/room-service/order-display/json', {
            method: 'POST',
            signal: activeFetchController.signal,
            headers: {
                'Content-Type': 'application/json',
                'X-Csrftoken': csrfToken,
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {}
            })
        });
        if (!response.ok) {
            setConnectionStatus('disconnected');
            return;
        }
        if (!canRenderMonitor()) {
            return;
        }
        const data = await response.json();
        if (canRenderMonitor() && data && data.result) {
            setConnectionStatus('live');
            ordersData = processRawOrders(data.result.orders);
            updateUI();
            updateSessionWarning(data.result.closed_sessions);
        } else {
            setConnectionStatus('disconnected');
        }
    } catch (e) {
        if (e.name === 'AbortError') {
            return;
        }
        console.error("Error polling orders:", e);
        setConnectionStatus('disconnected');
    } finally {
        activeFetchController = null;
    }
}

function updateUI() {
    if (!canRenderMonitor()) {
        return;
    }
    renderSummary();
    renderCards();
}

// Initialization
(function() {
    const root = document.querySelector('.rs-kds');
    if (!root) {
        return;
    }
    try {
        ordersData = processRawOrders(JSON.parse(root.dataset.orders || '[]'));
        const closedSessions = JSON.parse(root.dataset.closedSessions || '[]');
        updateSessionWarning(closedSessions);
    } catch (e) {
        console.error("Error loading initial orders:", e);
        ordersData = [];
    }
    renderSummary();
    if (ordersData && ordersData.length) {
        renderCards();
    } else {
        const grid = byId('orders-grid');
        if (grid) {
            grid.innerHTML = '<div class="rs-empty">Waiting for room service orders</div>';
        }
        renderOrder(null);
    }
    setConnectionStatus('live');

    // Start polling every 5 seconds
    pollingTimer = setInterval(fetchUpdatedOrders, 5000);
})();

                (function(){
                    // ── State ──
                    var cart = {}; // id -> {name, price, qty, note, img, hasImg}
                    var curPayment = 'bill_to_room';

                    // ── Payment default ──
                    document.getElementById('pm_room').checked = true;
                    document.querySelectorAll('.rso-pay-radio').forEach(function(r){
                        r.addEventListener('change', function(){
                            if(this.checked) curPayment = this.value;
                        });
                    });

                    // ── Helpers ──
                    function fmtPrice(p){
                        return p.toFixed(2);
                    }
                    function cartCount(){
                        return Object.values(cart).reduce(function(s,i){return s+i.qty;},0);
                    }
                    function cartTotal(){
                        return Object.values(cart).reduce(function(s,i){return s+i.qty*i.price;},0);
                    }

                    // ── Update UI after cart change ──
                    function refreshCTA(){
                        var count = cartCount();
                        var total = cartTotal();
                        var btn = document.getElementById('rs-view-cart-btn');
                        var badge = document.getElementById('rs-cart-count-badge');
                        var ctaTotal = document.getElementById('rs-cta-total');
                        btn.disabled = count === 0;
                        badge.textContent = count;
                        ctaTotal.textContent = fmtPrice(total);
                        // Update drawer total
                        document.getElementById('rs-drawer-total').textContent = fmtPrice(total);
                    }

                    function refreshCards(){
                        Object.keys(cart).forEach(function(id){
                            var card = document.querySelector('.rso-card[data-id="'+id+'"]');
                            var badge = document.getElementById('badge-'+id);
                            if(!card) return;
                            var qty = cart[id] ? cart[id].qty : 0;
                            card.classList.toggle('in-cart', qty>0);
                            if(badge) badge.textContent = qty;
                        });
                    }

                    function renderDrawer(){
                        var container = document.getElementById('rs-drawer-items');
                        container.innerHTML = '';
                        var ids = Object.keys(cart).filter(function(id){return cart[id].qty>0;});
                        if(ids.length === 0){
                            container.innerHTML = '
Your cart is empty';
                            return;
                        }
                        ids.forEach(function(id){
                            var item = cart[id];
                            var div = document.createElement('div');
                            div.className = 'rso-drawer-item';
                            var imgHTML = item.hasImg
                                ? ''
                                : '
';
                            div.innerHTML = imgHTML +
                                '
'+
                                  '
'+item.name+''+
                                  '
'+fmtPrice(item.price*item.qty)+''+
                                  ''+
                                ''+
                                '
'+
                                  '−'+
                                  ''+item.qty+''+
                                  '+'+
                                '';
                            container.appendChild(div);
                        });
                        // Note listeners
                        container.querySelectorAll('.rso-drawer-note').forEach(function(inp){
                            inp.addEventListener('input', function(){
                                if(cart[this.dataset.id]) cart[this.dataset.id].note = this.value;
                            });
                        });
                        // Qty listeners
                        container.querySelectorAll('.rso-drawer-qty-btn').forEach(function(btn){
                            btn.addEventListener('click', function(){
                                var id = this.dataset.id;
                                var action = this.dataset.action;
                                if(!cart[id]) return;
                                if(action==='plus') cart[id].qty++;
                                else cart[id].qty = Math.max(0, cart[id].qty-1);
                                if(cart[id].qty===0) delete cart[id];
                                renderDrawer(); refreshCTA(); refreshCards();
                            });
                        });
                    }

                    function escapeAttr(s){ return s.replace(/"/g,'"').replace(/'/g,'''); }

                    // ── Add to cart ──
                    document.querySelectorAll('.rso-card-add').forEach(function(btn){
                        btn.addEventListener('click', function(e){
                            e.stopPropagation();
                            var id = this.dataset.id;
                            var card = this.closest('.rso-card');
                            if(!cart[id]){
                                cart[id] = {
                                    name: card.dataset.name,
                                    price: parseFloat(card.dataset.price)||0,
                                    qty: 0,
                                    note: '',
                                    img: card.dataset.img,
                                    hasImg: card.dataset.hasImg==='1',
                                };
                            }
                            cart[id].qty++;
                            refreshCTA(); refreshCards();
                        });
                    });

                    // ── Tap card body = add 1 ──
                    document.querySelectorAll('.rso-card').forEach(function(card){
                        card.addEventListener('click', function(e){
                            if(e.target.closest('.rso-card-add')) return;
                            var id = card.dataset.id;
                            if(!cart[id]){
                                cart[id]={name:card.dataset.name,price:parseFloat(card.dataset.price)||0,qty:0,note:'',img:card.dataset.img,hasImg:card.dataset.hasImg==='1'};
                            }
                            cart[id].qty++;
                            refreshCTA(); refreshCards();
                        });
                    });

                    // ── Open/close drawer ──
                    document.getElementById('rs-view-cart-btn').addEventListener('click', function(){
                        if(cartCount()===0) return;
                        renderDrawer();
                        document.getElementById('rs-drawer').classList.add('open');
                        document.getElementById('rs-overlay').classList.add('open');
                    });
                    function closeDrawer(){
                        document.getElementById('rs-drawer').classList.remove('open');
                        document.getElementById('rs-overlay').classList.remove('open');
                    }
                    document.getElementById('rs-drawer-close').addEventListener('click', closeDrawer);
                    document.getElementById('rs-overlay').addEventListener('click', closeDrawer);

                    // ── Place order ──
                    document.getElementById('rs-place-btn').addEventListener('click', function(){
                        if(cartCount()===0) return;
                        var form = document.getElementById('rs-form');
                        document.getElementById('rs-pm-hidden').value = curPayment;
                        document.getElementById('rs-gn-hidden').value = document.getElementById('rs-gn').value;
                        var fieldsDiv = document.getElementById('rs-form-fields');
                        fieldsDiv.innerHTML = '';
                        Object.keys(cart).forEach(function(id){
                            var item = cart[id];
                            if(item.qty === 0) return;
                            var qtyInp = document.createElement('input');
                            qtyInp.type='hidden'; qtyInp.name='qty_'+id; qtyInp.value=item.qty;
                            fieldsDiv.appendChild(qtyInp);
                            var noteInp = document.createElement('input');
                            noteInp.type='hidden'; noteInp.name='note_'+id; noteInp.value=item.note||'';
                            fieldsDiv.appendChild(noteInp);
                        });
                        form.submit();
                    });

                    // ── Search ──
                    document.getElementById('rs-search').addEventListener('input', function(){
                        var q = this.value.toLowerCase().trim();
                        var anyVisible = false;
                        document.querySelectorAll('.rso-card').forEach(function(card){
                            var name = (card.dataset.name||'').toLowerCase();
                            var show = !q || name.includes(q);
                            card.classList.toggle('rso-hidden', !show);
                            if(show) anyVisible = true;
                        });
                        // Hide empty sections
                        document.querySelectorAll('.rso-section').forEach(function(sec){
                            var visCards = sec.querySelectorAll('.rso-card:not(.rso-hidden)');
                            sec.classList.toggle('rso-hidden', visCards.length===0);
                        });
                        document.getElementById('rs-no-results').classList.toggle('vis', !anyVisible && q.length>0);
                    });

                    // ── Category tabs ──
                    var catBtns = document.querySelectorAll('.rso-cat-btn');
                    var sections = document.querySelectorAll('.rso-section[data-section]');
                    if(catBtns.length>0){
                        catBtns[0].classList.add('active');
                        catBtns.forEach(function(btn){
                            btn.addEventListener('click', function(){
                                catBtns.forEach(function(b){b.classList.remove('active');});
                                this.classList.add('active');
                                var cat = this.dataset.cat;
                                var sec = document.querySelector('.rso-section[data-section="'+cat+'"]');
                                if(sec) sec.scrollIntoView({behavior:'smooth',block:'start'});
                            });
                        });
                        // IntersectionObserver for active tab highlight
                        if(sections.length){
                            var observer = new IntersectionObserver(function(entries){
                                entries.forEach(function(e){
                                    if(e.isIntersecting){
                                        var cat = e.target.dataset.section;
                                        catBtns.forEach(function(b){
                                            b.classList.toggle('active', b.dataset.cat===cat);
                                            if(b.dataset.cat===cat){
                                                b.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
                                            }
                                        });
                                    }
                                });
                            },{rootMargin:'-30% 0px -65% 0px'});
                            sections.forEach(function(s){observer.observe(s);});
                        }
                    }

                    // ── Init ──
                    refreshCTA();
                })();

(function(){
    var accessToken = "";
    var lastState   = "";

    var STEPS = [
        {states:['draft']},
        {states:['confirmed','pos_failed']},
        {states:['sent_pos']},
        {states:['kitchen_preparing']},
        {states:['kitchen_ready']},
        {states:['delivered','guest_confirmed']},
        {states:['folio_posted','paid_pos','closed']}
    ];
    var STATE_ICONS = {
        draft:'⏳', confirmed:'📋', sent_pos:'📬',
        pos_failed:'⚠', kitchen_preparing:'🍳', kitchen_ready:'👕',
        delivered:'🆕', guest_confirmed:'🎉', folio_posted:'✅',
        paid_pos:'✅', closed:'✅', cancelled:'🚫'
    };
    var STATE_DESCS = {
        draft:'We’ve received your order and it’s awaiting confirmation.',
        confirmed:'Your order has been confirmed and will be prepared shortly.',
        sent_pos:'Your order is being processed at the kitchen.',
        pos_failed:'There was an issue sending your order. Staff has been notified.',
        kitchen_preparing:'The kitchen is preparing your order now. 🍳',
        kitchen_ready:'Your order is ready and will be delivered shortly!',
        delivered:'Your order has been delivered. Enjoy your meal! 🍽',
        guest_confirmed:'Thank you for confirming receipt!',
        folio_posted:'Your bill has been posted to your room.',
        paid_pos:'Your order has been paid. Thank you!',
        closed:'Order complete. Thank you!',
        cancelled:'This order was cancelled.'
    };
    function escapeHtml(value){
        return String(value || '').replace(/[&<>"']/g,function(match){
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[match];
        });
    }

    function findStepIndex(state){
        if(state === 'cancelled') return STEPS.length;
        for(var i=0;i<STEPS.length;i++){
            if(STEPS[i].states.indexOf(state)!==-1) return i;
        }
        return -1;
    }
    function updateTracker(state){
        var tracker = document.getElementById('mo-tracker');
        var wraps = document.querySelectorAll('.mo-step-wrap');
        var idx = findStepIndex(state);
        if(tracker) tracker.classList.toggle('cancelled', state === 'cancelled');
        wraps.forEach(function(w,i){
            w.classList.remove('done','current','is-waiting');
            if(state === 'cancelled'){
                if(w.classList.contains('cancelled-step')) w.classList.add('current');
                return;
            }
            if(idx>=0){
                if(i<idx) w.classList.add('done');
                else if(i===idx){
                    w.classList.add('current');
                    if(['draft','confirmed','pos_failed'].indexOf(state)!==-1) w.classList.add('is-waiting');
                }
            }
        });
    }
    function updateTimestamp(displayValue){
        var target = document.getElementById('mo-updated');
        if(target && displayValue) target.textContent = 'Last updated ' + displayValue;
    }
    function applyState(state, label, updatedAtDisplay){
        var icon  = document.getElementById('mo-icon');
        var lbl   = document.getElementById('mo-state-label');
        var desc  = document.getElementById('mo-desc');
        if(icon) icon.innerHTML = STATE_ICONS[state]||'⏳';
        if(lbl){
            lbl.textContent = label;
            lbl.style.color = state === 'cancelled' ? '#dc2626' : '';
            lbl.classList.toggle('mo-pulse',['draft','confirmed','sent_pos','kitchen_preparing','kitchen_ready'].indexOf(state)!==-1);
        }
        if(desc) desc.innerHTML = STATE_DESCS[state]||'';
        updateTracker(state);
        updateTimestamp(updatedAtDisplay);
    }

    applyState(lastState, document.getElementById('mo-state-label').textContent.trim());

    async function checkStatus(){
        try{
            var r = await fetch('/room-service/order/'+accessToken+'/status/json',{
                method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{}})
            });
            var d = await r.json();
            if(d && d.result && !d.result.error){
                var changed = d.result.state !== lastState;
                lastState = d.result.state;
                applyState(d.result.state, d.result.state_label, d.result.updated_at_display);
                var box = document.getElementById('mo-confirm-box');
                if(box){
                    var ok=['sent_pos','kitchen_preparing','kitchen_ready','delivered'];
                    if(ok.indexOf(d.result.state)!==-1 && !box.querySelector('form')){
                        var csrf=(document.querySelector('input[name="csrf_token"]')||{}).value||'';
                        box.innerHTML='<form action="/room-service/order/'+accessToken+'/completed" method="post" style="margin-top:12px;">'+
                            '<input type="hidden" name="csrf_token" value="'+csrf+'"/>'+
                            '<button type="submit" class="mo-confirm-btn">&#10003;&#160;&#160;Confirm Delivered Correctly</button>'+
                            '</form>';
                    } else if(ok.indexOf(d.result.state)===-1){ box.innerHTML=''; }
                }
                var eb=document.getElementById('mo-error-box');
                if(eb) eb.innerHTML=d.result.last_error?'<div class="mo-error">'+escapeHtml(d.result.last_error)+'</div>':'';
            }
        }catch(e){console.error('Status check failed:',e);}
    }
    setInterval(checkStatus,5000);
})();

(function(){
    var accessToken = "";
    var lastState = "";

    /* ── step definitions (must match HTML data-states) ── */
    var STEPS = [
        {states:['draft']},
        {states:['confirmed','pos_failed']},
        {states:['sent_pos']},
        {states:['kitchen_preparing']},
        {states:['kitchen_ready']},
        {states:['delivered','guest_confirmed']},
        {states:['folio_posted','paid_pos','closed']}
    ];

    var STATE_ICONS = {
        draft:'⏳', confirmed:'📋', sent_pos:'📬',
        pos_failed:'⚠', kitchen_preparing:'🍳', kitchen_ready:'👕',
        delivered:'🆕', guest_confirmed:'🎉', folio_posted:'✅',
        paid_pos:'✅', closed:'✅', cancelled:'🚫'
    };
    var STATE_DESCS = {
        draft:'We’ve received your order and it’s awaiting confirmation.',
        confirmed:'Your order has been confirmed and will be prepared shortly.',
        sent_pos:'Your order is being processed at the kitchen.',
        pos_failed:'There was an issue sending your order. Staff has been notified.',
        kitchen_preparing:'The kitchen is preparing your order now. 🍳',
        kitchen_ready:'Your order is ready and will be delivered shortly!',
        delivered:'Your order has been delivered. Enjoy your meal! 🍽',
        guest_confirmed:'Thank you for confirming receipt!',
        folio_posted:'Your bill has been posted to your room.',
        paid_pos:'Your order has been paid. Thank you!',
        closed:'Order complete. Thank you!',
        cancelled:'This order was cancelled.'
    };

    function escapeHtml(value){
        return String(value || '').replace(/[&<>"']/g,function(match){
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[match];
        });
    }

    function findStepIndex(state){
        if(state === 'cancelled') return STEPS.length;
        for(var i=0;i<STEPS.length;i++){
            if(STEPS[i].states.indexOf(state) !== -1) return i;
        }
        return -1;
    }

    function updateTracker(state){
        var tracker = document.getElementById('st-tracker');
        var stepWraps = document.querySelectorAll('.st-step-wrap');
        var activeIdx = findStepIndex(state);
        if(tracker) tracker.classList.toggle('cancelled', state === 'cancelled');
        stepWraps.forEach(function(wrap, i){
            wrap.classList.remove('done','current','is-waiting');
            if(state === 'cancelled'){
                if(wrap.classList.contains('cancelled-step')) wrap.classList.add('current');
                return;
            }
            if(activeIdx >= 0){
                if(i < activeIdx) wrap.classList.add('done');
                else if(i === activeIdx){
                    wrap.classList.add('current');
                    if(['draft','confirmed','pos_failed'].indexOf(state)!==-1) wrap.classList.add('is-waiting');
                }
            }
        });
    }

    function updateTimestamp(displayValue){
        var target = document.getElementById('st-updated');
        if(target && displayValue) target.textContent = 'Last updated ' + displayValue;
    }

    function applyState(state, stateLabel, updatedAtDisplay){
        var iconEl  = document.getElementById('st-icon');
        var labelEl = document.getElementById('rso-state-label');
        var descEl  = document.getElementById('st-desc');
        if(iconEl)  iconEl.innerHTML  = STATE_ICONS[state]  || '⏳';
        if(labelEl){
            labelEl.textContent = stateLabel;
            labelEl.style.color = state === 'cancelled' ? '#dc2626' : '';
            var pulseStates = ['draft','confirmed','sent_pos','kitchen_preparing','kitchen_ready'];
            labelEl.classList.toggle('st-pulse', pulseStates.indexOf(state) !== -1);
        }
        if(descEl) descEl.innerHTML = STATE_DESCS[state] || '';
        updateTracker(state);
        updateTimestamp(updatedAtDisplay);
    }

    /* Init on page load */
    applyState(lastState, document.getElementById('rso-state-label').textContent.trim());

    /* ── poll for status updates every 5 s ── */
    async function checkStatus(){
        try{
            var resp = await fetch('/room-service/order/'+accessToken+'/status/json',{
                method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{}})
            });
            var data = await resp.json();
            if(data && data.result && !data.result.error){
                var r = data.result;
                lastState = r.state;
                applyState(r.state, r.state_label, r.updated_at_display);

                /* update confirm box */
                var confirmBox = document.getElementById('rso-confirm-box');
                if(confirmBox){
                    var csrf = (document.querySelector('input[name="csrf_token"]')||{}).value||'';
                    var cancelable = ['draft', 'confirmed', 'pos_failed'];
                    var confirmable = ['sent_pos','kitchen_preparing','kitchen_ready','delivered'];

                    var html = '';
                    if(cancelable.indexOf(r.state) !== -1) {
                        html += '<form action="/room-service/order/'+accessToken+'/cancel" method="post" style="margin-top:12px;">' +
                            '<input type="hidden" name="csrf_token" value="'+csrf+'"/>' +
                            '<button type="submit" class="st-cancel-btn" onclick="return confirm(\'Are you sure you want to cancel your order?\');" style="width:100%; padding:14px; border-radius:12px; border:1px solid #fee2e2; background:#fee2e2; color:#b91c1c; font-size:14px; font-weight:700; cursor:pointer; transition:all 0.2s; font-family:inherit;">Cancel Order</button>' +
                            '</form>';
                    } else if(confirmable.indexOf(r.state) !== -1) {
                        html += '<form action="/room-service/order/'+accessToken+'/completed" method="post" style="margin-top:12px;">'+
                            '<input type="hidden" name="csrf_token" value="'+csrf+'"/>'+
                            '<button type="submit" class="st-confirm-btn">&#10003;&#160;&#160;Confirm Delivered Correctly</button>'+
                            '</form>';
                    }
                    confirmBox.innerHTML = html;
                }

                /* update error box */
                var errBox = document.getElementById('rso-error-box');
                if(errBox) errBox.innerHTML = r.last_error ? '<div class="st-error">'+escapeHtml(r.last_error)+'</div>' : '';
            }
        }catch(e){console.error('Status check failed:',e);}
    }
    setInterval(checkStatus, 5000);
})();

const csrfToken = '';
const root = document.querySelector('.rs-room-status');
let roomsData = JSON.parse(root.dataset.rooms || '[]');
let zonesData = JSON.parse(root.dataset.zones || '[]');
let floorsData = JSON.parse(root.dataset.floors || '[]');
let summaryData = JSON.parse(root.dataset.summary || '{}');
let roomFilter = 'all';

function byId(id) {
    return document.getElementById(id);
}

function escapeHtml(value) {
    return String(value || '').replace(/[&<>"']/g, function(match) {
        return {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        }[match];
    });
}

function setOptions(select, values, allLabel) {
    const current = select.value || '';
    select.innerHTML = '<option value="">' + allLabel + '</option>' +
        values.map(value => '<option value="' + escapeHtml(value) + '">' + escapeHtml(value) + '</option>').join('');
    if ([...select.options].some(option => option.value === current)) {
        select.value = current;
    }
}

function renderFilters() {
    setOptions(byId('rs-zone-filter'), zonesData, 'All Buildings');
    setOptions(byId('rs-floor-filter'), floorsData, 'All Floors');
}

function renderSummary() {
    byId('summary-total').textContent = summaryData.total || 0;
    byId('summary-ordered').textContent = summaryData.ordered || 0;
    byId('summary-no-order').textContent = summaryData.no_order || 0;
}

function filteredRooms() {
    const query = (byId('rs-room-search').value || '').trim().toLowerCase();
    const zone = byId('rs-zone-filter').value || '';
    const floor = byId('rs-floor-filter').value || '';
    return roomsData.filter(room => {
        const orderMatch =
            roomFilter === 'all' ||
            (roomFilter === 'ordered' && room.has_order) ||
            (roomFilter === 'empty' && !room.has_order);
        const zoneMatch = !zone || room.zone === zone;
        const floorMatch = !floor || room.floor === floor;
        const queryMatch = !query ||
            String(room.number || '').toLowerCase().includes(query) ||
            String(room.guest || '').toLowerCase().includes(query);
        return orderMatch && zoneMatch && floorMatch && queryMatch;
    });
}

function openRoom(roomId) {
    const room = roomsData.find(item => item.id === Number(roomId));
    if (!room) {
        return;
    }
    if (room.order_id && room.order_url) {
        window.location.href = room.order_url;
        return;
    }
    const domain = encodeURIComponent(JSON.stringify([['room_id', '=', room.id]]));
    window.location.href = '/web#model=hotel.room.service.order&view_type=list&domain=' + domain;
}

function renderRooms() {
    const grid = byId('rs-room-grid');
    const rooms = filteredRooms();
    if (!rooms.length) {
        grid.innerHTML = '<div class="rs-empty">No rooms match the current filters.</div>';
        return;
    }
    grid.innerHTML = rooms.map(room => {
        const statusLine = room.has_order
            ? '<span class="rs-order-pill">' + escapeHtml(room.order_status || 'Active Order') + '</span>'
            : '<span class="rs-order-pill" style="background:#94a3b8;">No Active Order</span>';
        return '<article class="rs-room-card ' + (room.has_order ? 'has-order' : '') + '" data-room-id="' + room.id + '">' +
            '<div class="rs-room-number">' + escapeHtml(room.number || '-') + '</div>' +
            '<div class="rs-room-type">' + escapeHtml(room.type || 'No Room Type') + '</div>' +
            '<div class="rs-room-meta">' +
                '<div class="rs-room-line"><div class="rs-line-label">Guest</div><div class="rs-line-value">' + escapeHtml(room.guest || '-') + '</div></div>' +
                '<div class="rs-room-line"><div class="rs-line-label">Building / Floor</div><div class="rs-line-value">' + escapeHtml(room.zone || '-') + ' / ' + escapeHtml(room.floor || '-') + '</div></div>' +
            '</div>' +
            statusLine +
        '</article>';
    }).join('');
}

function updateLastUpdated() {
    const target = byId('rs-last-updated');
    if (target) {
        target.textContent = 'Last updated ' + new Date().toLocaleTimeString([], {hour: '2-digit', minute: '2-digit', second: '2-digit'});
    }
}

function updateAll() {
    renderSummary();
    renderRooms();
    updateLastUpdated();
}

async function refreshRoomStatus() {
    try {
        const response = await fetch('/room-service/room-status/json', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Csrftoken': csrfToken,
            },
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}}),
        });
        const data = await response.json();
        if (data && data.result) {
            roomsData = data.result.rooms || [];
            zonesData = data.result.zones || [];
            floorsData = data.result.floors || [];
            summaryData = data.result.summary || {};
            renderFilters();
            updateAll();
        }
    } catch (error) {
        console.error('Room status refresh failed:', error);
    }
}

byId('rs-room-search').addEventListener('input', renderRooms);
byId('rs-zone-filter').addEventListener('change', renderRooms);
byId('rs-floor-filter').addEventListener('change', renderRooms);
byId('rs-summary-cards').addEventListener('click', function(event) {
    const card = event.target.closest('.rs-summary-box');
    if (!card) {
        return;
    }
    roomFilter = card.dataset.filter || 'all';
    document.querySelectorAll('.rs-summary-box').forEach(function(box) {
        box.classList.toggle('active', box === card);
    });
    renderRooms();
});
byId('rs-room-grid').addEventListener('click', event => {
    const card = event.target.closest('.rs-room-card');
    if (card) {
        openRoom(card.dataset.roomId);
    }
});

renderFilters();
updateAll();
setInterval(refreshRoomStatus, 8000);
